<template>
    <tile
        title="My Forms"
        icon="icon-page"
        :nopadding="!loading"
        class="my-forms-widget"
        :loading="loading"
    >
        <div v-if="error" class="error-text">{{ error }}</div>
        <div v-else class="section">
            <div class="section-body nopadding">
                <div class="ui-inbox">
                    <div class="ui-inbox-labels">
                        <div class="button blue startnew" @click="openNewFormModal">Start a New Form</div>
                        <a class="button blue startnew" :href="inboxUrl" v-show="false">Inbox</a>
                        <span class="ui-inbox-loader" v-if="refreshing"></span>
                        <ul>
                            <li v-for="tab of tabs" @click="onTabClick(tab)" :class="{ selected: selectedTab == tab.name }">
                                <span class="indicator">{{ tab.count }}</span>
                                <span class="boxicon fonticon" :class="'icon-' + tab.icon"></span>
                                <span class="label">{{ tab.label }}</span>
                            </li>
                        </ul>
                    </div>
                    <div class="ui-inbox-boxes">
                        <component
                            v-on:refreshgrid="refreshGrid"
                            :is="selectedTab"
                            :data="currentPageData"
                        ></component>
                        <pager
                            name="inbox-pager"
                            v-if="currentData.length > 6"
                            :row-count="currentData.length"
                            :page-size="pageSize"
                            :page="page"
                            item-label="form(s)"
                            @goto="goToPage"
                        ></pager>
                    </div>
                </div>
            </div>
        </div>
        <modal :visible="newFormModalVisible" @close="onNewFormModalClose">
            <div class="spinnerbox large" v-if="formsLoading">
                <img :src="formsLoadImg" />
            </div>
            <div class="section" v-else>
                <form action="/CleverForms/StartNewForm">
                    <div class="default-form">
                        <div class="form-row">
                            <strong>Select a form to start</strong>
                        </div>
                        <div class="form-row">
                            <select ref="formSelector" class="width-full" name="templateAndWorkflowIds">
                                <option v-for="f of forms" :value="f ? f.TemplateId + ';' + f.WorkflowDefinitionId : ''">
                                    {{ f ? f.TemplateDescription + ' - ' + f.WorkflowName : '' }}
                                </option>
                            </select>
                        </div>
                        <div class="form-row">
                            <button
                                class="green"
                                type="submit"
                                @click="onFormStart($event)"
                            >
                                <span class="icon-tick"></span>
                                Start
                            </button>
                            <div
                                class="button grey cancel-button"
                                @click="onNewFormModalClose"
                            >
                                <span class="icon-cancel"></span>
                                Cancel
                            </div>
                        </div>
                    </div>
                </form>
            </div>
        </modal>
    </tile>
</template>

<script>
import Vue from "vue";
import ToAction from "./to-action-box.vue";
import InProgress from "./in-progress-box.vue";
import Completed from "./completed-box.vue";
import Tile from "../../common/tile";
import Modal from "../../common/modal";
import axios from "axios";
import moment from "moment";

export default {
    components: {
        ToAction,
        InProgress,
        Completed,
        Tile,
        Modal,
    },
    data() {
        return {
            tabs: [
                {
                    name: "ToAction",
                    icon: "download",
                    label: "To Action",
                    count: "0",
                },
                {
                    name: "InProgress",
                    icon: "clock",
                    label: "In Progress",
                    count: "0",
                },
                {
                    name: "Completed",
                    icon: "tick",
                    label: "Completed",
                    count: "0",
                },
            ],
            data: {
                ToAction: {
                    items: [],
                    totalCount: 0,
                    currentPage: 1,
                    pageSize: 25,
                    totalPages: 1
                },
                InProgress: {
                    items: [],
                    totalCount: 0,
                    currentPage: 1,
                    pageSize: 25,
                    totalPages: 1
                },
                Completed: {
                    items: [],
                    totalCount: 0,
                    currentPage: 1,
                    pageSize: 25,
                    totalPages: 1
                },
            },
            forms: [],
            formsLoading: false,
            formsLoadImg: document.config.loaders.large.light,
            newFormModalVisible: false,
            selectedTab: "ToAction",
            loading: true,
            refreshing: false,
            user: this.$user,
            page: 0,
            pageSize: 6,
            error: null,
        };
    },
    computed: {
        // CleverForms Inbox URL - uses dashboard wrapper path (not subdomain)
        // Dashboard proxies /CleverForms/* to the CleverForms app with auth
        inboxUrl() {
            return '/CleverForms/Inbox';
        },
        currentData() {
            return this.data[this.selectedTab]?.items || [];
        },
        currentPageData() {
            let data = [];
            let offset = this.page * this.pageSize;
            let threshold = Math.min(
                offset + this.pageSize,
                this.currentData.length
            );

            for (let i = offset; i < threshold; i++) {
                data.push(this.currentData[i]);
            }

            return data;
        },
    },
    methods: {
        openNewFormModal() {
            this.formsLoading = true;
            this.newFormModalVisible = true;

            this.getAvailableForms(() => {
                if (window.hasOwnProperty('UIAutoComplete'))
                {
                    new UIAutoComplete();
                }
                if (window.hasOwnProperty('UIAutoCompleteWidget'))
                {
                    new UIAutoCompleteWidget({
                        selectElement: this.$refs.formSelector,
                    });
                }
            });
            this.$registerAppcuesEvents("Dashboard.StartNewForm", "Start New Form has been clicked.");
        },
        onTabChanged(tab) {
            this.selectedTab = tab;
            this.getData();
        },
        onNewFormModalClose() {
            this.newFormModalVisible = false;
        },
        onFormStart(evt) {
            if (!this.$refs.formSelector.value) {
                evt.preventDefault();
                return false;
            }
            // iOS bfcache: Close modal before navigation to prevent stale UI on back
            if (window.autocompletes) window.autocompletes.hideAll();
            this.newFormModalVisible = false;
        },
        getAvailableForms(callback) {
            axios
                .get("/CleverForms/GetAvailableForms")
                .then(
                    (response) => {
                        this.forms = response.data.data;
                        this.forms.unshift(null);
                        this.formsLoading = false;
                        this.newFormModalVisible = false; //Forcing iOS to redraw

                        Vue.nextTick(() => {
                            this.newFormModalVisible = true; //Forcing iOS to redraw
                            if (callback) {
                                Vue.nextTick(() => {
                                    callback();
                                });
                            }
                        });
                    },
                    () => {
                        console.log("request failed");
                    }
                )
                .then(() => {
                    this.loading = false;
                });
        },
        refreshGrid() {
            this.getData();
        },
        getData() {
            this.refreshing = true;
            let searchCriteria = {
                CategorySettings: {
                    ToAction: {
                        PageSize: 5,
                        CurrentPage: 1,
                        SortFields: [{ Name: "StateEnteredAt", Ascending: false }]
                    },
                    InProgress: {
                        PageSize: 5,
                        CurrentPage: 1,
                        SortFields: [{ Name: "StateEnteredAt", Ascending: false }]
                    },
                    Completed: { 
                        PageSize: 5, 
                        CurrentPage: 1,
                        SortFields: [{ Name: "StateEnteredAt", Ascending: false }]
                    }
                },
                ActiveCategory: this.selectedTab,
                SearchQuery: null
            };
            axios.post('/CleverForms/FetchInboxData', searchCriteria)
                .then(response => {
                    let categorySettings = response.data.data.CategorySettings;
                    for (let name in this.tabMap) {
                        if (categorySettings[name]) {
                            let category = categorySettings[name];
                            // Format dates in the items array
                            if (category.Items) {
                                for (let i = 0; i < category.Items.length; i++) {
                                    if (category.Items[i].hasOwnProperty('EffectiveDate')) {
                                        if (moment(category.Items[i].EffectiveDate, "DD/MM/YYYY").isValid()) {
                                            let date = moment(category.Items[i].EffectiveDate, "DD/MM/YYYY");
                                            category.Items[i].EffectiveDate = date.format('YYYY-MM-DD') + 'T00:00:00Z';
                                        }
                                    }
                                    category.Items[i].DisplayName = category.Items[i].TemplateDescription;
                                }
                            }
                            this.tabMap[name].count = category.TotalCount.toString();
                            this.data[name] = {
                                items: category.Items,
                                totalCount: category.TotalCount,
                                currentPage: category.CurrentPage,
                                pageSize: category.PageSize,
                                totalPages: category.TotalPages
                            };
                        }
                    }
                    this.refreshing = false;
                }, () => {
                    this.error = 'Could not load forms.'
                }).then(() => {
                this.loading = false;
            })
        },
        goToPage(num) {
            this.page = num;
        },
        onTabClick(tab) {
            this.selectedTab = tab.name;
            this.page = 0;
            this.$registerAppcuesEvents(`Dashboard.${tab.name.replace(" ", "")}`, `${tab.name} has been clicked.`)
        },
        // iOS bfcache: Close modal and hide autocompletes on page restore
        onPageShow() {
            this.newFormModalVisible = false;
            if (window.autocompletes) window.autocompletes.hideAll();
        },
    },
    created() {
        this.tabMap = {};
        for (let i = 0; i < this.tabs.length; i++) {
            let tab = this.tabs[i];
            this.tabMap[tab.name] = tab;
        }

        this.getData();
    },
    mounted() {
        // iOS bfcache cleanup: Close modal on page restore
        window.addEventListener('pageshow', this.onPageShow);
    },
    beforeDestroy() {
        window.removeEventListener('pageshow', this.onPageShow);
    },
};
</script>

<style lang="scss" scoped>
.my-forms-widget {
    .ui-inbox {
        .ui-inbox-labels {
            position: relative;
            padding: 10px 120px 10px 0;
            box-sizing: border-box;

            @media screen and (max-width: 1280px) {
                padding-right: 150px;
                .button {
                    top: 5px;
                }
            }

            .button {
                position: absolute;
                right: 10px;
                top: 10px;
            }
            ul {
                li {
                    display: inline-block;
                    width: auto;
                    height: 36px;
                    line-height: 36px;
                    margin: 0 50px 0 0;
                    padding: 0 34px 0 0 !important;
                    color: #333333;
                    font-weight: 600;
                    font-size: 16px;
                    cursor: pointer;
                    
                    &.selected {
                        color: #007bff;
                        font-weight: 600;
                    }

                    .boxicon {
                        position: relative;
                        display: inline-block;
                        vertical-align: top;
                        height: 36px;
                        line-height: 36px;
                        margin: -2px 5px 0 0;
                        font-size: 20px;
                        color: #333333;
                    }

                    .indicator {
                        position: relative;
                        display: inline-flex;
                        align-items: center;
                        justify-content: center;
                        width: unset !important;
                        max-width: unset !important;
                        min-width: 20px;
                        height: 20px;
                        line-height: 20px;
                        margin: 0;
                        padding: 0 6px;
                        text-align: center;
                        font-size: 12px;
                        font-weight: normal !important;
                        color: #fff;
                        background: #8a99ab;
                        border-radius: 10px;
                        box-sizing: border-box;
                        transform: translateY(-2px);
                    }

                    &.selected {
                        .boxicon {
                            color: #007bff;
                            font-weight: normal;
                        }
                        .indicator {
                            background: #ff0000;
                            font-weight: normal;
                        }
                    }
                }
            }
        }
    }
}
</style>
