    .ui-inbox {
        box-shadow: none !important;
        .ui-inbox-labels {
            @media screen and (max-width: 1280px) {
                .button {
                }
            }
            .button {
                position: absolute;
                right: 10px;
                top: 10px;
            }
            ul {
                li {
                    width: auto;
                    max-width: unset;
                    padding: 0 34px 0 0 !important;
                }
            }
        }
    }
}
.ui-inbox-box {
    table.ui-grid {
        tr {
            th, td {
                padding: 10px;
                text-align: left;
                
                &:first-child {
                    width: unset !important;
                    max-width: 25% !important;
                }
                &.col-buttons {
                    width: unset !important;
                    min-width: 165px !important;
                }
            }
        }
    }
}
@media screen and (max-width: 560px) {
    body.newui .pagecontent .contentwrapper .my-forms-widget .section .section-body {
        .ui-inbox {
            .ui-inbox-labels {
                padding: 0 140px 10px 0 !important;
                top: unset !important;
                ul {
                    position: relative !important;
                    margin: 0 !important;
                    padding: 8px 0 0 0 !important;
                    box-sizing: border-box;
                    li {
                        display: inline-block !important;
                        width: 150px;
                        height: 36px;
                        min-width: unset;
                        max-width: unset;
                        line-height: 36px;
                        min-height: unset;
                        max-height: unset;
                        margin-right: 0 !important;
                        padding: 0 25px 0 0;
                        text-align: left;
                        box-sizing: border-box;
                        span {
                            &.boxicon {
                                height: 36px;
                                line-height: 36px;
                                width: 26px !important;
                                font-size: 14px !important;
                            }
                            &.label {
                                display: inline-block !important;
                                width: auto;
                                height: 36px;
                                left: unset;
                                bottom: unset;
                                line-height: 36px;
                            }
                            &.indicator {
                                right: 5px; 
                                width: 18px;
                                height: 18px;
                                line-height: 18px;
                                font-size: 12px;
                            }
                        }
                    }
                }
            }
        }
    }
}
</style>